async function api(path,options={}){
  const controller=options.signal?null:new AbortController();
  const timer=controller?setTimeout(()=>controller.abort(),30000):null;
  const method=String(options.method||'GET').toUpperCase();
  let body={};if(options.body){try{body=typeof options.body==='string'?JSON.parse(options.body):options.body}catch{body={}}}
  try{
    const response=await fetch(CLOUD_API,{method:'POST',headers:{'Content-Type':'application/json','apikey':CLOUD_KEY,...(ownerSession?{'x-kinoala-session':ownerSession}:{}),...(options.headers||{})},body:JSON.stringify({path,method,body}),signal:options.signal||controller?.signal});
    const data=await response.json().catch(()=>({}));
    if(response.status===401&&ownerSession){ownerSession='';localStorage.removeItem('kinoala_owner_session');isOwner=false;syncOwnerUi?.()}
    if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);
    return data;
  }catch(err){if(err?.name==='AbortError')throw new Error('Kinoala took too long to respond. Please try again.');throw err}
  finally{if(timer)clearTimeout(timer)}
}
function esc(v=''){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function reviewHtml(v=''){
  const raw=String(v??'');
  if(!raw.trim())return '<p class="review-empty">No written review.</p>';
  // <caption> is not valid as a free-standing HTML element, so normalize it to a
  // private element before DOMParser and render it back as a styled caption.
  const normalized=raw
    .replace(/<\s*caption\s*>/gi,'<kino-caption>')
    .replace(/<\s*\/\s*caption\s*>/gi,'</kino-caption>');
  const parsed=new DOMParser().parseFromString(`<div id="reviewSource">${normalized}</div>`,'text/html');
  const source=parsed.querySelector('#reviewSource');
  const out=document.createElement('div');
  const allowed=new Set(['B','STRONG','I','EM','BR','BLOCKQUOTE','P','A','H1','H2','H3','KINO-CAPTION']);
  const clean=node=>{
    if(node.nodeType===Node.TEXT_NODE){
      const frag=document.createDocumentFragment();String(node.nodeValue||'').split('\n').forEach((part,i,arr)=>{frag.append(document.createTextNode(part));if(i<arr.length-1)frag.append(document.createElement('br'))});return frag;
    }
    if(node.nodeType!==Node.ELEMENT_NODE)return document.createDocumentFragment();
    if(!allowed.has(node.tagName)){const frag=document.createDocumentFragment();[...node.childNodes].forEach(c=>frag.append(clean(c)));return frag}
    if(node.tagName==='KINO-CAPTION'){
      const el=document.createElement('div');el.className='review-caption';[...node.childNodes].forEach(c=>el.append(clean(c)));return el;
    }
    const tag=node.tagName==='B'?'strong':node.tagName==='I'?'em':node.tagName.toLowerCase();const el=document.createElement(tag);
    if(tag==='a'){const href=node.getAttribute('href')||'';if(/^https?:\/\//i.test(href)){el.href=href;el.target='_blank';el.rel='noopener noreferrer'}else{const frag=document.createDocumentFragment();[...node.childNodes].forEach(c=>frag.append(clean(c)));return frag}}
    [...node.childNodes].forEach(c=>el.append(clean(c)));return el;
  };
  [...source.childNodes].forEach(n=>out.append(clean(n)));
  if(!out.querySelector('p,blockquote,h1,h2,h3,.review-caption')){const p=document.createElement('p');while(out.firstChild)p.append(out.firstChild);out.append(p)}
  return out.innerHTML;
}
function today(){return new Date().toISOString().slice(0,10)}
function fmtDate(v){if(!v)return '—';const raw=String(v).slice(0,10);const d=new Date(`${raw}T12:00:00`);return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',year:'numeric'}).format(d)}
function shortDate(v){if(!v)return '';const d=new Date(`${String(v).slice(0,10)}T12:00:00`);return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short'}).format(d)}
function ratingText(v){return v==null?'':Number(v).toFixed(Number(v)%1?1:0)}
function tagChips(tags){if(!tags)return '';const items=String(tags).split(',').map(x=>x.trim()).filter(Boolean);return items.length?`<div class="tag-row">${items.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}
function reviewImagesHtml(entry,{compact=false}={}){
  const images=(entry?.review_images||[]).filter(Boolean);
  if(!images.length)return '';
  const shown=compact?images.slice(0,3):images;
  return `<div class="review-image-gallery ${compact?'compact':''}">${shown.map((src,i)=>`<figure><img loading="lazy" src="${esc(src)}" alt="Review image ${i+1}"></figure>`).join('')}${compact&&images.length>3?`<span class="review-image-more">+${images.length-3}</span>`:''}</div>`;
}
function reviewImageEditor(existing=null){
  const paths=existing?.review_image_paths||[];
  const urls=existing?.review_images||[];
  return `<div class="field full review-images-field"><label>Review images <span>optional · up to 8</span></label><div class="review-image-editor-grid" id="reviewImageExisting">${paths.map((path,i)=>`<div class="review-image-edit-item" data-review-image-path="${esc(path)}"><img src="${esc(urls[i]||'')}" alt=""><button type="button" aria-label="Remove image">×</button></div>`).join('')}</div><div class="review-image-editor-grid" id="reviewImageNewPreview"></div><input class="form-control" id="reviewImageInput" type="file" name="review_images" accept="image/png,image/jpeg,image/webp" multiple><small class="format-hint">Images appear beneath the written review. PNG, JPEG or WebP, up to 5 MB each.</small></div>`;
}
function bindReviewFormatting(textarea){
  if(!textarea)return;
  const formats={h1:['<h1>','</h1>','Heading'],h2:['<h2>','</h2>','Heading'],h3:['<h3>','</h3>','Heading'],b:['<b>','</b>','bold text'],i:['<i>','</i>','italic text'],quote:['<blockquote>','</blockquote>','Quote'],caption:['<caption>','</caption>','Caption']};
  $$('[data-review-format]',sheet).forEach(btn=>btn.onclick=()=>{
    const cfg=formats[btn.dataset.reviewFormat];if(!cfg)return;
    const start=textarea.selectionStart??textarea.value.length,end=textarea.selectionEnd??start;
    const selected=textarea.value.slice(start,end)||cfg[2];
    const replacement=`${cfg[0]}${selected}${cfg[1]}`;
    textarea.setRangeText(replacement,start,end,'select');textarea.focus();
  });
}
function reviewFormatToolbar(){
  return `<div class="review-format-toolbar" aria-label="Review formatting"><button type="button" data-review-format="h1">H1</button><button type="button" data-review-format="h2">H2</button><button type="button" data-review-format="h3">H3</button><span></span><button type="button" data-review-format="b"><b>B</b></button><button type="button" data-review-format="i"><i>I</i></button><button type="button" data-review-format="quote">❝</button><button type="button" data-review-format="caption">Caption</button></div>`;
}
function starIcons(value,size='normal'){
  const n=Number(value||0);
  return `<span class="stars-display ${size}" aria-label="${n||0} out of 5 stars">${[1,2,3,4,5].map(i=>{const fill=Math.max(0,Math.min(100,(n-(i-1))*100));return `<span class="star-shell"><span class="star-empty">★</span><span class="star-filled" style="width:${fill}%">★</span></span>`}).join('')}</span>`;
}
function ratingPicker(value,id,{clear=true}={}){
  const n=value==null?0:Number(value);
  return `<div class="rating-picker" id="${id}" data-value="${n}">${[1,2,3,4,5].map(i=>`<button type="button" class="rating-star-btn" data-star="${i}" aria-label="Rate ${i} stars"><span class="star-shell"><span class="star-empty">★</span><span class="star-filled">★</span></span></button>`).join('')}${clear?'<button type="button" class="rating-clear">clear</button>':''}</div>`;
}
function paintRatingPicker(root,value){if(!root)return;const n=Number(value||0);root.dataset.value=String(n);$$('.rating-star-btn',root).forEach(btn=>{const i=Number(btn.dataset.star);const fill=Math.max(0,Math.min(100,(n-(i-1))*100));$('.star-filled',btn).style.width=`${fill}%`})}
function bindRatingPicker(id,initial,onChange){
  const root=$(`#${id}`);if(!root)return;let saved=Number(initial||0);paintRatingPicker(root,saved);
  $$('.rating-star-btn',root).forEach(btn=>{
    btn.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=btn.getBoundingClientRect();const i=Number(btn.dataset.star);paintRatingPicker(root,i-(e.clientX-r.left<r.width/2?.5:0))});
    btn.addEventListener('click',async e=>{const r=btn.getBoundingClientRect();const i=Number(btn.dataset.star);saved=i-(e.clientX-r.left<r.width/2?.5:0);paintRatingPicker(root,saved);await onChange?.(saved)});
  });
  root.addEventListener('mouseleave',()=>paintRatingPicker(root,saved));
  $('.rating-clear',root)?.addEventListener('click',async()=>{saved=0;paintRatingPicker(root,0);await onChange?.(null)});
}
function typeLabel(m){return (m.media_type||'movie')==='tv'?'TV SERIES':'FILM'}
function posterHtml(m){return m.poster_url?`<img loading="lazy" src="${esc(m.poster_url)}" alt="${esc(m.title)} poster">`:`<div class="poster-placeholder"><span>${esc(m.title)}</span></div>`}
function filmCard(m,{compact=false,showTitle=true}={}){
  return `<article class="film-card ${compact?'compact':''}" data-film-id="${m.id}">
    <div class="poster">${posterHtml(m)}${m.media_type==='tv'?'<span class="media-pill">TV</span>':''}${m.liked?'<span class="poster-heart">♥</span>':''}</div>
    ${showTitle?`<div class="film-card-title" title="${esc(m.title)}">${esc(m.title)}</div><div class="film-card-meta"><span>${m.year||'—'}</span>${m.rating!=null?starIcons(m.rating,'tiny'):''}</div>`:''}
  </article>`;
}
function sectionRow(title,subtitle,items,view){if(!items?.length)return '';return `<section class="section"><div class="section-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${view?`<button data-view="${view}">View all →</button>`:''}</div><div class="poster-row">${items.map(x=>filmCard(x,{compact:true})).join('')}</div></section>`}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),3200)}
