function bindFilmCards(root=document){$$('[data-film-id]',root).forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('button,[data-log-type],[data-list-id]'))return;openMedia(Number(el.dataset.filmId))}))}
function bindViewLinks(root=document){$$('[data-view]',root).forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.view)))}
function bindLogLinks(root=document){$$('[data-log-type][data-log-id]',root).forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();openLogDetail(el.dataset.logType,Number(el.dataset.logId))}))}
function avatarMarkup(url,username,className='avatar'){const initial=esc((username||'K')[0]?.toUpperCase()||'K');return `<span class="${className}" data-avatar-fallback="${initial}">${url?`<img src="${esc(url)}" alt="" onerror="this.remove();this.parentElement.classList.add('avatar-fallback')">`:initial}</span>`}
function setMiniProfile(p={}){const target=$('#miniProfile');if(!target)return;const username=p.username||'kinoala';target.innerHTML=`${avatarMarkup(p.avatar_url,username)}<span class="mini-profile-copy"><strong>${esc(username)}</strong><small>${esc(p.location||'local profile')}</small></span>`}
