async function navigate(view){
  currentView=view;setActive(view);loading();searchPanel.classList.add('hidden');closeSheet();
  try{
    if(view==='profile')await renderProfile();
    else if(view==='films')await renderFilms();
    else if(view==='lists')await renderLists();
    else if(view==='watchlist')await renderWatchlist();
    else if(view==='activity')await renderActivity();
    else if(view==='settings')await renderSettings();
  }catch(e){content.innerHTML=`<div class="empty"><h3>Something went wrong</h3><p>${esc(e.message)}</p></div>`}
}

function ratingsHistogram(distribution,total,{compact=false}={}){
  const buckets=[.5,1,1.5,2,2.5,3,3.5,4,4.5,5];const counts=buckets.map(r=>Number(distribution.find(x=>Number(x.rating)===r)?.count||0));const max=Math.max(...counts,1);
  return `<section class="ratings-histogram ${compact?'compact':''}"><div class="ratings-title"><span>RATINGS</span><b>${total||counts.reduce((a,b)=>a+b,0)}</b></div><div class="rating-rule"></div><div class="histogram-body"><div class="histogram-edge one">★</div><div class="histogram-bars">${counts.map((c,i)=>`<div class="histogram-column" title="${buckets[i]} stars · ${c}"><i style="height:${c?Math.max(3,c/max*100):2}%"></i></div>`).join('')}</div><div class="histogram-edge five">★★★★★</div></div></section>`
}
function logSubtitle(x){if(x.log_type==='season')return `Season ${x.season_number}`;if(x.log_type==='episode')return `S${String(x.season_number||0).padStart(2,'0')}E${String(x.episode_number||0).padStart(2,'0')} · ${x.episode_name||'Episode'}`;if(x.log_type==='review'&&x.media_type==='tv')return 'Series review';return x.rewatch?'Rewatch':'Film'}
function compactLog(x){return `<button class="compact-log" data-log-type="${x.log_type}" data-log-id="${x.log_id}"><div class="compact-log-poster">${x.poster_url?`<img src="${esc(x.poster_url)}" alt="">`:''}</div><div class="compact-log-copy"><strong>${esc(x.title)} <span>${x.year||''}</span></strong><small>${esc(logSubtitle(x))} · ${fmtDate(x.watched_date)}</small>${x.rating!=null?starIcons(x.rating,'tiny'):''}${x.review?`<p>${esc(String(x.review).replace(/<[^>]+>/g,'').slice(0,150))}</p>`:''}</div>${x.liked?'<i class="log-like">♥</i>':''}</button>`}

function topFiveCard(m,index){
  if(!m)return `<button class="top5-empty" data-empty-top5="${index}"><span>＋</span><b>Add film</b></button>`;
  const bg=m.backdrop_url?`style="background-image:linear-gradient(180deg,rgba(9,13,16,.08) 0%,rgba(9,13,16,.38) 36%,rgba(12,16,19,.98) 100%),url('${esc(m.backdrop_url)}')"`:'';
  return `<article class="top5-card" data-film-id="${m.id}" ${bg}><div class="top5-rank">0${index+1}</div><div class="top5-content"><div class="top5-poster">${posterHtml(m)}</div><div class="top5-copy"><h3>${esc(m.title)}</h3><span>${m.year||''}</span>${m.rating!=null?starIcons(m.rating,'small'):''}</div></div></article>`;
}
function profileDiary(logs,total){
  const rows=(logs||[]).slice(0,9);
  if(!rows.length)return `<section class="profile-side-block"><div class="profile-block-head"><span>DIARY</span><b>${total||0}</b></div><div class="profile-rule"></div><div class="empty compact">No diary entries yet.</div></section>`;
  const groups=[];for(const x of rows){const d=new Date(`${String(x.watched_date).slice(0,10)}T12:00:00`);const key=`${d.getFullYear()}-${d.getMonth()}`;let g=groups.at(-1);if(!g||g.key!==key){g={key,month:d.toLocaleString('en-AU',{month:'short'}).toUpperCase(),items:[]};groups.push(g)}g.items.push(x)}
  return `<section class="profile-side-block"><div class="profile-block-head"><span>DIARY</span><b>${total||rows.length}</b></div><div class="profile-rule"></div><div class="profile-diary">${groups.map(g=>`<div class="diary-month"><div class="diary-month-badge">${g.month}</div><div class="diary-month-items">${g.items.map(x=>`<button data-log-type="${x.log_type}" data-log-id="${x.log_id}"><time>${new Date(`${String(x.watched_date).slice(0,10)}T12:00:00`).getDate()}</time><span>${esc(x.title)}</span></button>`).join('')}</div></div>`).join('')}</div></section>`;
}
function profileActivity(actions,username){
  const rows=(actions||[]).slice(0,6);if(!rows.length)return '';
  const describe=a=>{if(a.action==='logged')return `watched <strong>${esc(a.title||'a film')}</strong>`;if(a.action==='rated')return `rated <strong>${esc(a.title||'a title')}</strong> ${a.rating!=null?starIcons(a.rating,'tiny'):''}`;if(a.action==='liked')return `liked <strong>${esc(a.title||'a title')}</strong>`;if(a.action==='reviewed')return `reviewed <strong>${esc(a.title||'a title')}</strong>`;if(a.action==='created_list')return `created <strong>${esc(a.list_name||a.details||'a list')}</strong>`;if(a.action==='added_to_list')return `added <strong>${esc(a.title||'a title')}</strong> to ${esc(a.list_name||'a list')}`;if(a.action==='logged_season')return `logged Season ${a.season_number||''} of <strong>${esc(a.title||'a show')}</strong>`;if(a.action==='logged_episode')return `logged an episode of <strong>${esc(a.title||'a show')}</strong>`;return `updated <strong>${esc(a.title||a.list_name||'the library')}</strong>`};
  return `<section class="profile-side-block profile-activity-block"><div class="profile-block-head"><span>ACTIVITY</span><button data-view="activity">ALL</button></div><div class="profile-rule"></div><div class="profile-activity-timeline">${rows.map(a=>`<div class="profile-activity-item"><i></i><p><b>${esc(username)}</b> ${describe(a)} <time>${fmtDate(a.created_at)}</time></p></div>`).join('')}</div></section>`;
}
function recentReviewItem(x){
  const context=x.log_type==='season'?`<span class="review-context">Season ${x.season_number}</span>`:(x.log_type==='review'&&x.media_type==='tv'?'<span class="review-context">Series review</span>':'');
  return `<button class="profile-review-row" data-log-type="${x.log_type}" data-log-id="${x.log_id}"><div class="profile-review-poster">${x.poster_url?`<img src="${esc(x.poster_url)}" alt="">`:''}</div><div class="profile-review-copy"><div class="profile-review-title"><h3>${esc(x.title)}</h3><span>${x.year||''}</span></div>${context}<div class="profile-review-meta">${x.rating!=null?starIcons(x.rating,'small'):''}<span>Watched ${fmtDate(x.watched_date)}</span>${x.rewatch?'<span>↻ Rewatch</span>':''}${x.liked?'<span class="liked-text">♥ Liked</span>':''}</div><div class="profile-review-text">${reviewHtml(x.review)}</div>${reviewImagesHtml(x,{compact:true})}${tagChips(x.tags)}</div></button>`;
}
async function renderProfile(){
  const d=await api('/api/profile');cachedProfile=d.profile;setMiniProfile(d.profile);const p=d.profile;const username=p.username||'kinoala';const top=p.top5||p.top4||[];
  content.innerHTML=`<div class="profile-page"><section class="profile-header">${avatarMarkup(p.avatar_url,username,'profile-avatar')}<div class="profile-main"><div class="profile-name-row"><h1>${esc(username)}</h1><button class="secondary small" id="editProfile">Edit profile</button></div><div class="profile-meta">${p.pronoun?`<span>${esc(p.pronoun)}</span>`:''}${p.location?`<span>⌖ ${esc(p.location)}</span>`:''}</div><p>${esc(p.bio||'')}</p></div><div class="profile-stats"><div><strong>${d.stats.movies_watched||0}</strong><span>Films</span></div><div><strong>${d.stats.shows_watched||0}</strong><span>Shows</span></div><div><strong>${d.stats.episode_logs||0}</strong><span>Episodes</span></div><div><strong>${d.stats.lists||0}</strong><span>Lists</span></div></div></section>
    <section class="section profile-top5"><div class="section-head"><div><h2>Favourite Films</h2></div></div><div class="top5-row">${[0,1,2,3,4].map(i=>topFiveCard(top[i],i)).join('')}</div></section>
    <div class="profile-columns"><div class="profile-column-main">
      ${sectionRow('Recent films and Shows','',d.recent,'activity')}
      ${d.recent_reviews?.length?`<section class="section recent-reviews-section"><div class="section-head"><div><h2>Recent reviews</h2></div><button data-view="activity">More →</button></div><div class="profile-review-list">${d.recent_reviews.slice(0,4).map(recentReviewItem).join('')}</div></section>`:''}
      <section class="section"><div class="section-head"><div><h2>Lists</h2></div><button data-view="lists">View all →</button></div><div class="profile-list-row">${d.lists.slice(0,5).map(listCard).join('')||'<div class="empty">No lists yet.</div>'}</div></section>
    </div><aside class="profile-column-side">
      ${profileDiary(d.diary,d.stats.diary)}
      ${ratingsHistogram(d.ratingDistribution,d.stats.rated,{compact:true})}
      ${profileActivity(d.activities,username)}
    </aside></div></div>`;
  $('#editProfile').onclick=()=>openProfileEditor(d);$$('[data-empty-top5]').forEach(b=>b.onclick=()=>openProfileEditor(d));bindFilmCards(content);bindViewLinks(content);bindLogLinks(content);$$('[data-list-id]').forEach(el=>el.onclick=()=>showList(Number(el.dataset.listId)));
}

async function renderFilms(){
  content.innerHTML=`<div class="eyebrow">Your library</div><h1 class="page-title">Films & TV</h1><p class="page-subtitle">Everything you have added to Kinoala.</p><div class="toolbar browse-toolbar"><input id="filmFilter" type="search" placeholder="Filter your library…"><select id="mediaType"><option value="all">Films & TV</option><option value="movie">Films</option><option value="tv">TV shows</option></select><select id="filmSort"><option value="title">Title A–Z</option><option value="year">Release year</option><option value="rating">Your rating</option><option value="recent">Recently updated</option></select><label class="check-line"><input id="watchedOnly" type="checkbox"> Watched only</label><span class="spacer"></span><span id="filmCount" class="page-subtitle"></span></div><div id="filmGrid" class="film-grid"></div>`;
  const load=async()=>{const grid=$('#filmGrid');grid.innerHTML='<div class="loading-state"><div class="spinner"></div></div>';const params=new URLSearchParams({q:$('#filmFilter').value,type:$('#mediaType').value,sort:$('#filmSort').value});if($('#watchedOnly').checked)params.set('watched','1');const rows=await api(`/api/films?${params}`);$('#filmCount').textContent=`${rows.length} titles`;grid.innerHTML=rows.length?rows.map(filmCard).join(''):'<div class="empty">No titles match this filter.</div>';bindFilmCards(grid)};
  let t;$('#filmFilter').addEventListener('input',()=>{clearTimeout(t);t=setTimeout(load,170)});$('#mediaType').addEventListener('change',load);$('#filmSort').addEventListener('change',load);$('#watchedOnly').addEventListener('change',load);await load();
}
async function renderWatchlist(){const rows=await api('/api/watchlist');content.innerHTML=`<div class="eyebrow">Up next</div><div class="title-row"><div><h1 class="page-title">Watchlist</h1><p class="page-subtitle">Films and shows you want to get around to.</p></div><button class="primary" id="watchlistAdd">＋ Add title</button></div><div class="film-grid">${rows.map(filmCard).join('')||'<div class="empty">Your watchlist is empty.</div>'}</div>`;$('#watchlistAdd').onclick=focusSearch;bindFilmCards(content)}

