async function renderLists(){const lists=await api('/api/lists');content.innerHTML=`<div class="eyebrow">Collections</div><div class="title-row"><div><h1 class="page-title">Lists</h1><p class="page-subtitle">Personal collections with optional square artwork.</p></div><button class="primary" id="newList">＋ New list</button></div><div class="list-grid spotify-lists">${lists.map(listCard).join('')||'<div class="empty">Create your first list.</div>'}</div>`;$('#newList').onclick=()=>openListEditor();$$('[data-list-id]').forEach(el=>el.onclick=()=>showList(Number(el.dataset.listId)))}
async function showList(id){const lists=await api('/api/lists');const list=lists.find(l=>l.id===id);if(!list)return;content.innerHTML=`<button class="back-link" id="backLists">← All lists</button><section class="list-detail-head">${autoListCover(list)}<div><div class="eyebrow">List</div><h1>${esc(list.name)}</h1><p>${esc(list.description||'')}</p><div class="list-detail-actions"><span>${list.items.length} titles</span><button class="secondary" id="editList">Edit list</button></div></div></section><div class="film-grid">${list.items.map(filmCard).join('')||'<div class="empty">This list is empty.</div>'}</div>`;$('#backLists').onclick=renderLists;$('#editList').onclick=()=>openListEditor(list);bindFilmCards(content)}

function featuredLog(x){const bg=x.backdrop_url?`style="background-image:linear-gradient(180deg,rgba(15,19,22,.12),rgba(15,19,22,.92) 72%,#0f1316),url('${esc(x.backdrop_url)}')"`:'';return `<button class="featured-log" data-log-type="${x.log_type}" data-log-id="${x.log_id}" ${bg}><div class="featured-log-inner"><div class="featured-poster">${x.poster_url?`<img src="${esc(x.poster_url)}" alt="">`:''}</div><div class="featured-copy"><div class="eyebrow">Most recent</div><h2>${esc(x.title)}</h2><div class="featured-meta">${x.rating!=null?starIcons(x.rating,'small'):''}<span>${fmtDate(x.watched_date)}</span>${x.liked?'<span class="liked-text">♥ liked</span>':''}${x.rewatch?'<span>↻ rewatch</span>':''}</div><div class="featured-sub">${esc(logSubtitle(x))}</div>${x.review?`<div class="featured-review">${reviewHtml(x.review)}</div>`:'<p class="page-subtitle">No written review for this entry.</p>'}${tagChips(x.tags)}</div></div></button>`}
async function renderActivity(){
  const [logs,actions]=await Promise.all([api('/api/logs?limit=300'),api('/api/activity?limit=120')]);
  const latest=logs.find(x=>String(x.review||'').trim())||logs[0];const older=latest?logs.filter(x=>!(x.log_type===latest.log_type&&Number(x.log_id)===Number(latest.log_id))):[];
  content.innerHTML=`<div class="eyebrow">Your viewing history</div><div class="title-row"><div><h1 class="page-title">Activity</h1><p class="page-subtitle">Logs, reviews, rewatches, seasons and episodes in chronological order.</p></div><button class="primary" id="activityAdd">＋ Log something</button></div>${latest?featuredLog(latest):'<div class="empty">Nothing logged yet.</div>'}${older.length?`<section class="section"><div class="section-head"><div><h2>Earlier entries</h2><p>Open an entry to see its full review and previous reviews for the same title.</p></div></div><div class="compact-log-list activity-log-list">${older.map(compactLog).join('')}</div></section>`:''}${actions.length?`<details class="other-activity"><summary>Library activity</summary><div class="activity-feed">${actions.slice(0,80).map(activityRow).join('')}</div></details>`:''}`;
  $('#activityAdd').onclick=focusSearch;bindLogLinks(content);bindFilmCards(content);
}
function activityRow(a){const target=a.title?`<strong>${esc(a.title)}</strong>`:a.list_name?`<strong>${esc(a.list_name)}</strong>`:'your library';let text='updated';if(a.action==='logged')text='watched';else if(a.action==='rated')text=`rated ${a.rating!=null?starIcons(a.rating,'tiny'):''}`;else if(a.action==='liked')text='liked';else if(a.action==='watchlisted')text='added to watchlist';else if(a.action==='reviewed')text='reviewed';else if(a.action==='created_list')text='created list';else if(a.action==='added_to_list')text=`added to ${esc(a.list_name||'a list')}`;else if(a.action==='logged_season')text=`logged Season ${a.season_number}`;else if(a.action==='logged_episode')text=`logged S${String(a.season_number||0).padStart(2,'0')}E${String(a.episode_number||0).padStart(2,'0')}`;else if(a.action==='marked_watched')text='marked watched';return `<div class="activity-row" ${a.media_id?`data-film-id="${a.media_id}"`:''}><div class="activity-thumb">${a.poster_url?`<img src="${esc(a.poster_url)}" alt="">`:'<span>●</span>'}</div><div><p>${text} ${target}</p>${a.details?`<small>${esc(String(a.details).replace(/<[^>]+>/g,'').slice(0,140))}</small>`:''}</div><time>${shortDate(a.created_at)}</time></div>`}

